src/hooks/useTheme.ts.diff:
@@ -0,0 +1,35 @@
+import { useEffect, useState } from "react";
+
+export type Theme = "light" | "dark";
+
+const query = "(prefers-color-scheme: dark)";
+
+const system = (): Theme =>
+  matchMedia(query).matches ? "dark" : "light";
+
+const saved = (): Theme | null => {
+  const t = localStorage.theme;
+  return t === "dark" || t === "light" ? t : null;
+};
+
+export function useTheme() {
+  const [choice, setChoice] = useState(saved);
+  const [os, setOs] = useState(system);
+  const theme = choice ?? os;
+
+  useEffect(() => {
+    const media = matchMedia(query);
+    const follow = () => setOs(system());
+    media.addEventListener("change", follow);
+    return () =>
+      media.removeEventListener("change", follow);
+  }, []);
+
+  useEffect(() => {
+    const root = document.documentElement;
+    root.dataset.theme = theme;
+    if (choice) localStorage.theme = choice;
+  }, [theme, choice]);
+
+  return [theme, setChoice] as const;
+}

